// Escape website, one Framer code file. The site (14 components, 4,600 lines of TSX) is bundled,
// minified and gzip-compressed below; this wrapper decompresses it in the browser and renders it.
// Source of truth: EscapeLLC/code/*.tsx (edit there and rebuild; do not edit the blob by hand).
import * as React from "react"
import * as JSX from "react/jsx-runtime"
import * as Framer from "framer"
import * as Motion from "framer-motion"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

interface SiteProps { startPage: string; gateFirst: boolean; pageTitles: boolean }

let modP: Promise<any> | null = null
async function load() {
    const bin = Uint8Array.from(atob(SITE_GZ_B64.replace(/\s+/g, "")), (c) => c.charCodeAt(0))
    const stream = new Blob([bin]).stream().pipeThrough(new (window as any).DecompressionStream("gzip"))
    const js = await new Response(stream).text()
    const factory = new Function("React", "Framer", "Motion", "JSX", js)
    return factory(React, Framer, Motion, JSX)
}

/** @framerSupportedLayoutWidth any @framerSupportedLayoutHeight any */
export default function EscapeSite(p: SiteProps) {
    const [Site, setSite] = React.useState<any>(null)
    const [err, setErr] = React.useState("")
    React.useEffect(() => {
        let on = true
        ;(modP ||= load()).then((m) => { if (on) setSite(() => m.default) }, (e) => { if (on) setErr(String(e && e.message || e)) })
        return () => { on = false }
    }, [])
    if (Site) return <Site {...p} />
    const canvas = RenderTarget.current() === RenderTarget.canvas
    return (
        <div style={{ minHeight: canvas ? 320 : "100vh", width: "100%", background: "#0B1230", color: "#E6EAF4", display: "grid", placeItems: "center", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>
            {err ? <span>Escape site failed to load: {err}</span> : <span style={{ opacity: 0.5 }}>Escape</span>}
        </div>
    )
}

EscapeSite.defaultProps = { startPage: "home", gateFirst: true, pageTitles: true }
addPropertyControls(EscapeSite, {
 gateFirst: { type: ControlType.Boolean, title: "Start at orb gate", defaultValue: true, enabledTitle: "Yes", disabledTitle: "No" },
 startPage: {
 type: ControlType.Enum, title: "Show page", defaultValue: "home",
 description: "The page shown on the canvas, and the first page when the orb gate is off.",
 options: ["gate", "home", "lucille", "marketplace", "pricing", "innerverse", "beta", "demo", "privacy", "health", "terms", "safety", "deleteAccount", "cookies"],
 optionTitles: ["Orb gate", "Home", "Lucille AI", "Marketplace", "Pricing", "Innerverse", "App testing (beta)", "App demo", "Privacy", "Health data", "Terms", "Safety", "Delete account", "Cookies"],
 },
 pageTitles: { type: ControlType.Boolean, title: "Tab titles", defaultValue: true, enabledTitle: "Per page", disabledTitle: "Framer's" },
})

const SITE_GZ_B64 = `
































































































































































































































































TH2S26/59NVQqLK/pkOL5aHMeptbWwJDhqnJVF7isJzNwd20H8wVqJZL7iKMNDjVn0V5fDzGAige3qEACoUpvAOsND7eMGZ5bSY+/Em8WcQJvvzy2Jsa9q5c9hDeUI5WMEJeI3VTMTw1DDu5iBoHNeCnhTqPUc4G8U1HwgaEaTbPA3nZvCVFUyyNI2nwRUkaa7svDTgsxmww0OKs7NIP/wHgx4HG5uQDAA==
`
